{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would replace the definition of \"bullying\" in Section 39-17-308(e). Bullying would mean an act by a school employee or a student that substantially interferes with a victim's educational benefits, opportunities, or performance. The act must also meet one of two tests. If it happens on school grounds, at a school-sponsored activity, on school-provided equipment or transportation, or at an official school bus stop, it must have the effect of physically harming the victim or damaging the victim's property, or knowingly placing the victim in reasonable fear of such harm or damage. If it happens off school property or outside a school-sponsored activity, it must be aimed specifically at a victim or victims and must substantially disrupt the education environment or learning process.",
      "rationale": "Conveys the replacement definition, covered actors, substantial educational interference requirement, and both location-specific tests with their material conditions."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would add two definitions. A \"school employee\" would be an employee of a private school, a local education agency, a public charter school, or another public school.",
      "rationale": "Includes all four categories of school employees covered by the added definition."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "A \"victim\" would be any student if the act is committed by a school employee, or another student if the act is committed by a student.",
      "rationale": "Accurately conveys both actor-dependent branches of the victim definition."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would amend Section 49-6-4503(b)(3) by adding \"and school employee\" after \"each student.\"",
      "rationale": "Identifies the exact amendment target and textual insertion."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It would also add a new subsection to Section 49-6-4503. Under it, a teacher or school employee found to have committed harassment, intimidation, bullying, or cyberbullying would be subject to dismissal or suspension.",
      "rationale": "Includes the covered personnel, finding of misconduct, all four types of misconduct, and both disciplinary consequences."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Finally, the bill would add a new item to Section 49-5-501(7). It would list committing harassment, intimidation, bullying, or cyberbullying in violation of the school district's policy under chapter 6, part 45 of Title 49 among the matters covered in that subdivision.",
      "rationale": "Identifies the amendment target, all listed conduct, and the requirement that the conduct violate the district policy under the specified statutory part."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "It would take effect July 1, 2026, and would apply to acts committed on or after that date.",
      "rationale": "States both the effective date and the prospective applicability condition."
    }
  ]
}
